def check_condition(n):
    return (3 * n**2 + n) % 4 == 0

# Check for n in the range [99, 110]
results = {}
for n in range(99, 111):
    results[n] = check_condition(n)

print("n | 3n^2 + n mod 4 == 0")
print("-" * 30)
for n, satisfies in results.items():
    print(f"{n} | {satisfies}")
